// Aruncă paginile-director și listicle-urile ("Top 10 firme...", clasamente, recenzii)
const badName = /(\btop\s*\d+|cele mai bune|cei mai buni|clasament|\bdirector(y)?\b|lista de|recenzii|\breviews?\b|compara)/i;
const badPath = /\/(top[-_]?\d*|clasament|director|lista|reviews?|recenzii)(\/|$|-)/i;
const out = [];
for (const item of $input.all()) {
  const c = item.json;
  let path = '';
  try { path = new URL(c.Website).pathname; } catch (e) {}
  if (!c.Website || badName.test(String(c.Nume || '')) || badPath.test(path)) {
    console.log('Respinsa (pagina-director/listicle): ' + c.Nume);
    continue;
  }
  out.push({ json: c });
}
return out;

const results = [];
for (const item of $input.all()) {
  const c = item.json;
  const prompt = `Esti un expert in calificarea prospectilor B2B pentru o firma mica de servicii AI/automatizari pentru IMM-uri. Analizeaza compania de mai jos si raspunde STRICT cu un JSON valid, fara alt text in afara lui, de forma exacta: {"scor": <numar 1-10>, "eticheta": "calificat sau necalificat", "motiv": "un motiv scurt, o propozitie"}.

Companie: ${c.Nume}
Website: ${c.Website}
Descriere: ${c.Descriere}
Industrie: ${c.Industrie}

Reguli: pragul de calificare este scor mai mare sau egal cu 6. Companiile mici (IMM), fara semne vizibile de automatizare/chatbot pe site, sunt candidati mai buni.`;

  const body = {
    model: "claude-haiku-4-5",
    max_tokens: 300,
    temperature: 0,
    messages: [{ role: "user", content: prompt }]
  };

  results.push({
    json: {
      Nume: c.Nume,
      Website: c.Website,
      Descriere: c.Descriere,
      Industrie: c.Industrie,
      _claudeRequestBody: JSON.stringify(body)
    }
  });
}
return results;

const originals = $('Pregateste prompt Claude').all();
const responses = $input.all();
const results = [];
for (let i = 0; i < responses.length; i++) {
  const resp = responses[i].json;
  const orig = originals[i].json;
  let scor = null, eticheta = "eroare", motiv = "nu s-a putut interpreta raspunsul";
  try {
    const text = resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
    const match = text.match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(match[0]);
    scor = parsed.scor;
    eticheta = String(parsed.eticheta).trim().toLowerCase();
    motiv = parsed.motiv;
  } catch (e) {
    motiv = "eroare la parsare: " + e.message;
  }

  let domain = "";
  try {
    let urlStr = orig.Website || "";
    if (!/^https?:\/\//i.test(urlStr)) { urlStr = "https://" + urlStr; }
    domain = new URL(urlStr).hostname.replace(/^www\./i, "");
  } catch (e) {
    domain = (orig.Website || "").replace(/^https?:\/\//i, "").replace(/^www\./i, "").split("/")[0];
  }

  const hubspotBody = {
    properties: {
      name: orig.Nume,
      domain: domain,
      description: `ICP: ${eticheta} (scor ${scor}/10) - ${motiv}`
    }
  };
  const searchBody = {
    filterGroups: [{ filters: [{ propertyName: "domain", operator: "EQ", value: domain }] }],
    properties: ["domain", "name"],
    limit: 1
  };

  results.push({
    json: {
      Nume: orig.Nume,
      Website: orig.Website,
      Descriere: orig.Descriere,
      Industrie: orig.Industrie,
      Domain: domain,
      ScorICP: scor,
      EtichetaICP: eticheta,
      MotivICP: motiv,
      _hubspotRequestBody: JSON.stringify(hubspotBody),
      _searchBody: JSON.stringify(searchBody)
    }
  });
}
return results;

// Dacă HubSpot a găsit deja firma (după domeniu), păstrăm id-ul => nodul următor face PATCH (actualizare), altfel POST (creare)
const originals = $('Interpreteaza scor si pregateste HubSpot').all();
return $input.all().map((r, i) => {
  const orig = originals[i].json;
  const found = r.json && r.json.results && r.json.results[0];
  const id = found ? String(found.id) : null;
  return { json: { ...orig, _companyId: id, _existaInHubSpot: !!id, _cautareEsuata: !!(r.json && r.json.error) } };
});

const originals = $('Decide creare sau actualizare').all();
return $input.all().map((r, i) => {
  const orig = originals[i].json;
  const id = r.json && r.json.id ? String(r.json.id) : null;
  const calificat = String(orig.EtichetaICP).toLowerCase() === 'calificat';
  const query = `contact echipa despre noi ${orig.Domain}`;
  return {
    json: {
      ...orig,
      CompanyId: id,
      _hubspotOk: !!id,
      _dealName: `${orig.Domain} — Funnel B2B`,
      _dealSearchBody: JSON.stringify({
        filterGroups: [{ filters: [{ propertyName: 'dealname', operator: 'EQ', value: `${orig.Domain} — Funnel B2B` }] }],
        properties: ['dealname', 'dealstage'],
        limit: 1
      }),
      _calificat: calificat,
      _firecrawlBody: JSON.stringify({ query, limit: 3, includeDomains: [orig.Domain], scrapeOptions: { formats: ['markdown'], onlyMainContent: true } })
    }
  };
});

// Deal existent (găsit după nume) => PATCH fără să-i atingem etapa; altfel POST în etapa "Nou", asociat cu firma
const originals = $('Dupa Company pregateste').all();
return $input.all().map((r, i) => {
  const o = originals[i].json;
  const found = r.json && r.json.results && r.json.results[0];
  const id = found ? String(found.id) : null;
  const create = { properties: { dealname: o._dealName, pipeline: '4207689945', dealstage: '6186488008' } };
  if (o.CompanyId) {
    create.associations = [{ to: { id: o.CompanyId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 5 }] }];
  }
  const body = id ? { properties: { dealname: o._dealName } } : create;
  return { json: { ...o, _dealId: id, _dealBody: JSON.stringify(body) } };
});

const originals = $('Decide deal').all();
return $input.all().map((r, i) => {
  const o = originals[i].json;
  const id = r.json && r.json.id ? String(r.json.id) : null;
  return {
    json: {
      ...o,
      DealId: id,
      _dealUrl: 'https://api.hubapi.com/crm/v3/objects/deals/' + (id || 0),
      _dealCalificatBody: JSON.stringify({ properties: { dealstage: '6186488009' } }),
      _dealDraftBody: JSON.stringify({ properties: { dealstage: '6186488010' } })
    }
  };
});

const originals = $('Dupa Deal').all().filter(x => x.json._calificat);
return $input.all().map((r, i) => ({
  json: { ...originals[i].json, _dealCalificat: !(r.json && r.json.error) }
}));

const originals = $('Dupa Calificat').all();
return $input.all().map((r, i) => {
  const orig = originals[i].json;
  const pages = (r.json && r.json.data && r.json.data.web) || [];
  const siteText = pages
    .map(p => `## ${p.url}\n${String(p.markdown || '').slice(0, 5000)}`)
    .join('\n\n')
    .slice(0, 12000);
  const prompt = `Din textul paginilor de mai jos ale firmei "${orig.Nume}", extrage persoana de decizie cea mai potrivita (fondator, administrator, director, manager, partener, medic-sef). Raspunde STRICT cu un JSON valid, fara alt text, de forma exacta: {"gasit": true sau false, "nume": "", "rol": "", "email": "", "telefon": "", "sursa": "url-ul paginii"}.
Reguli: NU inventa nimic. Daca pe pagini nu apare un nume de persoana, pune gasit=false si lasa campurile goale. Pune email doar daca apare explicit in text (poate fi si un email de contact al firmei).

TEXT PAGINI:
${siteText || '(nu s-a gasit niciun text)'}`;
  return {
    json: {
      ...orig,
      _siteText: siteText,
      _paginiGasite: pages.length,
      _claudeContactBody: JSON.stringify({ model: 'claude-haiku-4-5', max_tokens: 400, temperature: 0, messages: [{ role: 'user', content: prompt }] })
    }
  };
});

const originals = $('Pregateste prompt contact').all();
return $input.all().map((r, i) => {
  const orig = originals[i].json;
  let c = { gasit: false, nume: '', rol: '', email: '', telefon: '', sursa: '' };
  try {
    const text = r.json.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
    c = { ...c, ...JSON.parse(text.match(/\{[\s\S]*\}/)[0]) };
  } catch (e) {}
  const email = String(c.email || '').trim().toLowerCase();
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const nume = String(c.nume || '').trim();
  const gasit = c.gasit === true && nume.length > 0;
  const parts = nume.split(/\s+/);
  const props = { firstname: parts[0] || '', lastname: parts.slice(1).join(' '), jobtitle: String(c.rol || '') };
  if (c.telefon) props.phone = String(c.telefon);
  const areEmail = gasit && emailOk;
  return {
    json: {
      ...orig,
      Contact: { nume: gasit ? nume : '', rol: gasit ? String(c.rol || '') : '', email: emailOk ? email : '', telefon: String(c.telefon || ''), sursa: String(c.sursa || '') },
      ContactStatus: gasit ? (emailOk ? 'gasit' : 'gasit-fara-email') : 'negasit',
      _areEmail: areEmail,
      _contactBody: JSON.stringify({ inputs: [{ idProperty: 'email', id: email, properties: props }] })
    }
  };
});

const originals = $('Are email').all(0); // doar ramura "da"
return $input.all().map((r, i) => {
  const orig = originals[i].json;
  const res = r.json && r.json.results && r.json.results[0];
  const contactId = res ? String(res.id) : null;
  const ok = contactId && orig.CompanyId;
  return {
    json: {
      ...orig,
      ContactId: contactId,
      _assocUrl: `https://api.hubapi.com/crm/v4/objects/contacts/${ok ? contactId : 0}/associations/default/companies/${ok ? orig.CompanyId : 0}`
    }
  };
});

const originals = $('Prepara asociere').all();
return $input.all().map((r, i) => ({
  json: { ...originals[i].json, _asociat: !(r.json && r.json.error) }
}));

return $input.all().map(item => {
  const c = item.json;
  const areNume = c.Contact && c.Contact.nume;
  const salut = areNume ? `Bună ziua, ${c.Contact.nume},` : 'Bună ziua,';
  const contactInfo = areNume
    ? `${c.Contact.nume} (${c.Contact.rol || 'rol necunoscut'})`
    : 'NEGĂSIT — folosește un salut generic, fără nume';
  const prompt = `Ești Adelina Sidor, consultant care oferă servicii de automatizare și AI pentru IMM-uri (de exemplu: chatbot pe site, automatizarea răspunsurilor la clienți, integrare CRM, rapoarte automate). Scrie un email de prezentare și conținutul unei oferte personalizate pentru firma de mai jos, în limba română, cu diacritice, ton profesionist și cald.

REGULI STRICTE:
- Nu inventa clienți, cifre, statistici, prețuri sau servicii pe care textul de pe site nu le menționează.
- Fiecare pain-point trebuie legat de un detaliu concret din textul de pe site. Dacă textul nu are destule detalii, scrie exact „DETALII INSUFICIENTE pe site" în loc să inventezi.
- Emailul are maxim 150 de cuvinte, fără formulări generice de tip „am observat compania dumneavoastră".
- La prețul din ofertă scrie exact: [PREȚ DE COMPLETAT de Adelina].

DATE FIRMĂ:
Nume: ${c.Nume}
Website: ${c.Website}
Industrie: ${c.Industrie}
Scor ICP: ${c.ScorICP}/10 — ${c.MotivICP}
Persoană de contact: ${contactInfo}

TEXT DE PE SITE:
${c._siteText || '(niciun text găsit)'}

FORMAT EXACT AL RĂSPUNSULUI (fără alt text în afara lui):
### SUBIECT
(o singură linie)
### EMAIL
(începe cu: ${salut} — semnează: Adelina Sidor)
### PAIN POINTS
(2-3 puncte cu liniuță)
### OFERTA
(secțiuni cu titluri: Situația actuală; Ce propunem; Pași de implementare; Rezultate așteptate; Investiție; Pasul următor)`;
  return {
    json: {
      ...c,
      _claudeOfertaBody: JSON.stringify({ model: 'claude-sonnet-5-5', max_tokens: 6000, messages: [{ role: 'user', content: prompt }] })
    }
  };
});

const DIR = 'C:\\Users\\Adi\\Curs-AI-Accelerator\\PROIECTELE MELE\\FUNNEL DE VANZARI\\oferte-de-aprobat';
const originals = $('Pregateste prompt oferta').all();
const items = $input.all();
const out = [];
const q = v => '"' + String(v == null ? '' : v).replace(/"/g, '\\"') + '"';
for (let i = 0; i < items.length; i++) {
  const r = items[i].json;
  const c = originals[i].json;
  let text = '';
  try { text = r.content.filter(b => b.type === 'text').map(b => b.text).join('\n'); } catch (e) {}
  if (r.stop_reason === 'max_tokens') console.log('Oferta taiata (max_tokens) pentru: ' + c.Nume);
  if (!text) { console.log('Fara oferta generata pentru: ' + c.Nume); continue; }
  const slug = String(c.Domain || 'firma').replace(/[^a-z0-9]+/gi, '-');
  const front = [
    '---',
    'status: în așteptare',
    'firma: ' + q(c.Nume),
    'website: ' + q(c.Website),
    'scor_icp: ' + c.ScorICP,
    'contact: ' + q(c.Contact && c.Contact.nume),
    'rol_contact: ' + q(c.Contact && c.Contact.rol),
    'email_contact: ' + q(c.Contact && c.Contact.email),
    'contact_status: ' + c.ContactStatus,
    'hubspot_company_id: ' + q(c.CompanyId),
    'hubspot_deal_id: ' + q(c.DealId),
    'generat: ' + new Date().toISOString().slice(0, 10),
    '---'
  ].join('\n');
  const content = front + '\n\n> DRAFT — neaprobat. Citește, apoi schimbă `status` în `aprobat` sau `respins` (sus, în capul fișierului).\n\n' + text + '\n';
  const bin = await this.helpers.prepareBinaryData(Buffer.from(content, 'utf8'), slug + '.md', 'text/markdown');
  out.push({
    json: { Nume: c.Nume, _fileName: DIR + '\\' + slug + '.md', DealId: c.DealId, _dealUrl: c._dealUrl, _dealDraftBody: c._dealDraftBody },
    binary: { data: bin }
  });
}
return out;

// După scrierea fișierului: păstrăm datele Deal-ului ca să-l mutăm în "Draft email"
const originals = $('Pregateste fisier aprobare').all();
return $input.all().map((r, i) => ({ json: { ...originals[i].json } }));

// Păstrăm rezultatele căutării și pregătim cererea "map" (harta site-ului, fără să depindă de index)
const originals = $('Dupa Calificat').all();
return $input.all().map((r, i) => {
  const orig = originals[i].json;
  const pages = (r.json && r.json.data && r.json.data.web) || [];
  return { json: {
    _domain: orig.Domain,
    _searchPages: pages,
    _mapBody: JSON.stringify({ url: 'https://' + orig.Domain, search: 'contact echipa despre noi', limit: 30 })
  } };
});

// Pregătește citirea paginii principale (cu toate linkurile, inclusiv din meniu)
const prev = $('Pregateste harta').all();
return $input.all().map((r, i) => {
  const p = prev[i].json;
  const mapLinks = ((r.json && r.json.links) || []).map(l => typeof l === 'string' ? l : (l && l.url)).filter(Boolean);
  return { json: { _domain: p._domain, _searchPages: p._searchPages, _mapLinks: mapLinks,
    _scrapeHome: JSON.stringify({ url: 'https://' + p._domain + '/', formats: ['markdown', 'links'], onlyMainContent: false }) } };
});

// Alege pagina de contact și pe cea de echipă din linkurile găsite (harta + pagina principală)
const prev = $('Pregateste pagina principala').all();
return $input.all().map((r, i) => {
  const p = prev[i].json;
  const home = 'https://' + p._domain + '/';
  const d = (r.json && r.json.data) || {};
  const links = [...new Set([...(d.links || []), ...(p._mapLinks || [])])].filter(u => typeof u === 'string' && u.includes(p._domain));
  const path = u => String(u).replace(/^https?:\/\/[^\/]+/, '');
  const contact = links.find(u => /contact|kontakt/i.test(path(u))) || home;
  const team = links.find(u => u !== contact && /echipa|despre|about|team|noi/i.test(path(u))) || home;
  const body = u => JSON.stringify({ url: u, formats: ['markdown'], onlyMainContent: true, maxAge: 0 });
  return { json: { _domain: p._domain, _searchPages: p._searchPages,
    _homeMarkdown: d.markdown || '', _u1: contact, _u2: team, _scrape1: body(contact), _scrape2: body(team) } };
});

// Unește paginile din căutare cu cele citite direct; același format ca la căutare: data.web[{url, markdown}]
const prev = $('Alege pagini').all();
const s1 = $('Citeste pagina contact Firecrawl').all();
return $input.all().map((r, i) => {
  const p = prev[i].json;
  const web = [...(p._searchPages || [])];
  const home = 'https://' + p._domain + '/';
  if (p._homeMarkdown) web.push({ url: home, markdown: p._homeMarkdown });
  const add = (resp, u) => {
    const d = resp && resp.json && resp.json.data;
    if (d && d.markdown) web.push({ url: (d.metadata && (d.metadata.sourceURL || d.metadata.url)) || u, markdown: d.markdown });
  };
  add(s1[i], p._u1);
  add(r, p._u2);
  const seen = new Set();
  const out = web.filter(x => { const k = String(x.url).replace(/\/$/, ''); if (seen.has(k)) return false; seen.add(k); return true; });
  return { json: { data: { web: out } } };
});
